// Strategies: a declarative description of how a player bets, plus an executor that
// turns that description into concrete bets on a PlayerSession before every roll.
//
// Declarative → the same JSON object can be edited in the UI, saved to localStorage,
// shipped to a Web Worker, generated by the permutation explorer, and executed.

import { POINT_NUMBERS, ALL_BOX_NUMBERS, HARD_NUMBERS, PROP_TYPES, PROPS, STANDING_TYPES, isPointNumber } from './constants.js';
import { UNITS, LAY_ODDS, maxOddsMultiple, vigFor, roundPayout, PLACE_ODDS, TRUE_ODDS, ODDS_LIMITS, houseEdge } from './rules.js';
import { Progression, PROGRESSIONS } from './progressions.js';
import { minimumFor } from './session.js';

export const ODDS_CHOICES = [0, 1, 2, 3, 5, 10, 20, 100, 'max'];
export const PLACE_ON_HIT = {
  collect: 'Collect (keep bet the same)',
  press: 'Full press (double the bet)',
  halfPress: 'Half press (+50%)',
  regress: 'Regress to table minimum after first hit',
};
export const WHEN_CHOICES = {
  pointOn: 'Only while a point is on',
  always: 'Every roll (incl. come-out)',
  comeOut: 'Only on come-out rolls',
};

const zeroMap = (keys) => Object.fromEntries(keys.map((k) => [k, 0]));

let idCounter = 0;
export const newId = () => `s${Date.now().toString(36)}${(idCounter++).toString(36)}${Math.floor(Math.random() * 1e4).toString(36)}`;

export function defaultStrategy() {
  return {
    id: newId(),
    name: 'New strategy',
    notes: '',
    line: { type: 'pass', amount: 10, odds: 0 },
    come: { count: 0, amount: 10, odds: 0 },
    dontCome: { count: 0, amount: 10, odds: 0 },
    place: { amounts: zeroMap(ALL_BOX_NUMBERS), buy: [], when: 'pointOn', skipCovered: false, onHit: 'collect', maxPress: 4, downAfterHits: 0 },
    lay: { amounts: zeroMap(POINT_NUMBERS), when: 'pointOn' },
    field: { amount: 0, when: 'always' },
    hard: { amounts: zeroMap(HARD_NUMBERS), when: 'pointOn' },
    props: { amounts: zeroMap(PROP_TYPES), when: 'comeOut' },
    big: { amounts: { 6: 0, 8: 0 } },
    progression: { type: 'flat', target: 'line', maxMultiplier: 32, paroliSteps: 3 },
  };
}

const num = (v, d = 0) => (Number.isFinite(+v) ? Math.max(0, +v) : d);
const oddsVal = (v) => (v === 'max' ? 'max' : ODDS_CHOICES.includes(+v) ? +v : 0);

/** Fill missing fields and coerce types so any partial/old JSON is safe to run. */
export function normalizeStrategy(input = {}) {
  const d = defaultStrategy();
  const s = { ...d, ...input };
  s.id = input.id || d.id;
  s.name = String(input.name ?? d.name).slice(0, 80);
  s.notes = String(input.notes ?? '').slice(0, 500);
  s.line = { ...d.line, ...(input.line || {}) };
  if (!['none', 'pass', 'dontPass'].includes(s.line.type)) s.line.type = 'none';
  s.line.amount = num(s.line.amount, 10); s.line.odds = oddsVal(s.line.odds);
  for (const k of ['come', 'dontCome']) {
    s[k] = { ...d[k], ...(input[k] || {}) };
    s[k].count = Math.min(6, Math.floor(num(s[k].count)));
    s[k].amount = num(s[k].amount, 10); s[k].odds = oddsVal(s[k].odds);
  }
  const ip = input.place || {};
  s.place = { ...d.place, ...ip, amounts: { ...d.place.amounts, ...(ip.amounts || {}) } };
  for (const n of ALL_BOX_NUMBERS) s.place.amounts[n] = num(s.place.amounts[n]);
  s.place.buy = Array.isArray(ip.buy) ? ip.buy.map(Number).filter((n) => ALL_BOX_NUMBERS.includes(n)) : [];
  if (!WHEN_CHOICES[s.place.when] || s.place.when === 'comeOut') s.place.when = 'pointOn';
  if (!PLACE_ON_HIT[s.place.onHit]) s.place.onHit = 'collect';
  s.place.skipCovered = !!s.place.skipCovered;
  s.place.maxPress = Math.max(1, num(s.place.maxPress, 4));
  s.place.downAfterHits = Math.floor(num(s.place.downAfterHits));
  const il = input.lay || {};
  s.lay = { ...d.lay, ...il, amounts: { ...d.lay.amounts, ...(il.amounts || {}) } };
  for (const n of POINT_NUMBERS) s.lay.amounts[n] = num(s.lay.amounts[n]);
  if (!WHEN_CHOICES[s.lay.when] || s.lay.when === 'comeOut') s.lay.when = 'pointOn';
  s.field = { ...d.field, ...(input.field || {}) };
  s.field.amount = num(s.field.amount);
  if (!WHEN_CHOICES[s.field.when]) s.field.when = 'always';
  const ih = input.hard || {};
  s.hard = { ...d.hard, ...ih, amounts: { ...d.hard.amounts, ...(ih.amounts || {}) } };
  for (const n of HARD_NUMBERS) s.hard.amounts[n] = num(s.hard.amounts[n]);
  if (!WHEN_CHOICES[s.hard.when] || s.hard.when === 'comeOut') s.hard.when = 'pointOn';
  const ipr = input.props || {};
  s.props = { ...d.props, ...ipr, amounts: { ...d.props.amounts, ...(ipr.amounts || {}) } };
  for (const p of PROP_TYPES) s.props.amounts[p] = num(s.props.amounts[p]);
  if (!WHEN_CHOICES[s.props.when]) s.props.when = 'comeOut';
  const ib = input.big || {};
  s.big = { amounts: { 6: num(ib.amounts?.[6]), 8: num(ib.amounts?.[8]) } };
  s.progression = { ...d.progression, ...(input.progression || {}) };
  if (!PROGRESSIONS[s.progression.type]) s.progression.type = 'flat';
  if (!['line', 'field'].includes(s.progression.target)) s.progression.target = 'line';
  s.progression.maxMultiplier = Math.max(1, num(s.progression.maxMultiplier, 32));
  s.progression.paroliSteps = Math.max(1, Math.floor(num(s.progression.paroliSteps, 3)));
  return s;
}

// ---------------------------------------------------------------------------
// Validation & description
// ---------------------------------------------------------------------------

const money = (x) => `$${(Math.round(x * 100) / 100).toLocaleString('en-US')}`;

/** Lists every individual bet a strategy makes, with its base amount. Used by validation & the cost preview. */
export function strategyBets(s) {
  const out = [];
  if (s.line.type !== 'none' && s.line.amount > 0) out.push({ type: s.line.type, amount: s.line.amount, label: s.line.type === 'pass' ? 'Pass Line' : "Don't Pass" });
  if (s.come.count > 0 && s.come.amount > 0) out.push({ type: 'come', amount: s.come.amount, label: `Come (×${s.come.count})` });
  if (s.dontCome.count > 0 && s.dontCome.amount > 0) out.push({ type: 'dontCome', amount: s.dontCome.amount, label: `Don't Come (×${s.dontCome.count})` });
  for (const n of ALL_BOX_NUMBERS) {
    const a = s.place.amounts[n];
    if (a > 0) { const t = s.place.buy.includes(n) ? 'buy' : 'place'; out.push({ type: t, number: n, amount: a, label: `${t === 'buy' ? 'Buy' : 'Place'} ${n}` }); }
  }
  for (const n of POINT_NUMBERS) if (s.lay.amounts[n] > 0) out.push({ type: 'lay', number: n, amount: s.lay.amounts[n], label: `Lay ${n}` });
  if (s.field.amount > 0) out.push({ type: 'field', amount: s.field.amount, label: 'Field' });
  for (const n of HARD_NUMBERS) if (s.hard.amounts[n] > 0) out.push({ type: 'hard', number: n, amount: s.hard.amounts[n], label: `Hard ${n}` });
  for (const p of PROP_TYPES) if (s.props.amounts[p] > 0) out.push({ type: p, amount: s.props.amounts[p], label: PROPS[p].label });
  for (const n of [6, 8]) if (s.big.amounts[n] > 0) out.push({ type: 'big', number: n, amount: s.big.amounts[n], label: `Big ${n}` });
  return out;
}

export function validateStrategy(input, rules) {
  const s = normalizeStrategy(input);
  const errors = [], warnings = [];
  const bets = strategyBets(s);
  if (!bets.length) errors.push('This strategy makes no bets. Add at least one bet amount.');
  const crapless = rules.game === 'crapless';
  if (crapless && (s.line.type === 'dontPass' || s.dontCome.count > 0)) errors.push("Crapless craps has no Don't Pass or Don't Come bets.");
  for (const b of bets) {
    if ((b.type === 'place' || b.type === 'buy') && !isPointNumber(b.number, rules)) {
      errors.push(`${b.label}: 2, 3, 11 and 12 are only box numbers at a Crapless craps table (Table Rules → Game).`);
      continue;
    }
    if (PROPS[b.type]?.units && b.amount % PROPS[b.type].units !== 0) {
      warnings.push(`${b.label}: bet in multiples of $${PROPS[b.type].units} (it is split equally across ${PROPS[b.type].units === 4 ? '2, 3, 11 and 12' : 'Any Craps and 11'}); odd amounts are paid rounded down.`);
    }
    const min = minimumFor(b.type, b.number, rules);
    if (b.amount < min - 1e-9) errors.push(`${b.label}: ${money(b.amount)} is below the table minimum of ${money(min)}.`);
    if (b.amount > rules.tableMax + 1e-9) errors.push(`${b.label}: ${money(b.amount)} exceeds the table maximum of ${money(rules.tableMax)}.`);
    if (rules.rounding !== 'exact') {
      if (b.type === 'place' && b.amount % UNITS.place[b.number] !== 0) {
        const fair = b.amount * PLACE_ODDS[b.number];
        warnings.push(`${b.label}: ${money(b.amount)} is not a multiple of $${UNITS.place[b.number]}, so a win pays ${money(roundPayout(fair, rules))} instead of ${money(fair)} (raises the edge to ${(houseEdge('place', b.number, b.amount, rules) * 100).toFixed(2)}%).`);
      }
      if (b.type === 'buy') {
        const vig = vigFor(b.amount, rules);
        if (vig / b.amount > rules.vigRate + 1e-6) warnings.push(`${b.label}: the $1 minimum commission on a ${money(b.amount)} buy is ${((vig / b.amount) * 100).toFixed(1)}% — buy in ${money(Math.ceil(1 / rules.vigRate))}+ increments to get the full 5% rate.`);
        if (b.amount % UNITS.buy[b.number] !== 0) warnings.push(`${b.label}: true-odds payout ${money(b.amount * TRUE_ODDS[b.number])} will be rounded down.`);
      }
      if (b.type === 'lay') {
        const win = roundPayout(b.amount * LAY_ODDS[b.number], rules);
        const vig = vigFor(win, rules);
        if (win > 0 && vig / win > rules.vigRate + 1e-6) warnings.push(`${b.label}: commission is ${((vig / win) * 100).toFixed(1)}% of the win at this size (lay to win $20+ for the true 5%).`);
      }
    }
  }
  if (s.line.type === 'none' && s.line.odds) warnings.push('Line odds are ignored because there is no line bet.');
  if (s.progression.type !== 'flat') {
    if (s.progression.target === 'line' && s.line.type === 'none') warnings.push('Progression targets the line bet, but there is no line bet — it will have no effect.');
    if (s.progression.target === 'field' && !(s.field.amount > 0)) warnings.push('Progression targets the Field, but there is no field bet — it will have no effect.');
    const base = s.progression.target === 'field' ? s.field.amount : s.line.amount;
    if (base * s.progression.maxMultiplier > rules.tableMax) warnings.push(`Progression cap ${s.progression.maxMultiplier}× would exceed the ${money(rules.tableMax)} table max; bets are clamped to the max.`);
  }
  if (s.come.count > 0 && s.dontCome.count > 0) warnings.push('Betting both Come and Don\'t Come mostly cancels out while paying the edge on both.');
  return { errors, warnings, strategy: s };
}

const oddsText = (o) => (o === 'max' ? 'max odds' : `${o}x odds`);

export function describeStrategy(input) {
  const s = normalizeStrategy(input);
  const parts = [];
  if (s.line.type !== 'none') parts.push(`${s.line.type === 'pass' ? 'Pass' : "Don't Pass"} ${money(s.line.amount)}${s.line.odds ? ` + ${oddsText(s.line.odds)}` : ''}`);
  if (s.come.count) parts.push(`${s.come.count} Come ${money(s.come.amount)}${s.come.odds ? ` + ${oddsText(s.come.odds)}` : ''}`);
  if (s.dontCome.count) parts.push(`${s.dontCome.count} Don't Come ${money(s.dontCome.amount)}${s.dontCome.odds ? ` + ${oddsText(s.dontCome.odds)}` : ''}`);
  const placed = ALL_BOX_NUMBERS.filter((n) => s.place.amounts[n] > 0);
  if (placed.length) {
    const tot = placed.reduce((a, n) => a + s.place.amounts[n], 0);
    const buys = placed.filter((n) => s.place.buy.includes(n));
    let t = `${buys.length === placed.length ? 'Buy' : 'Place'} ${placed.join('/')} (${money(tot)})`;
    if (s.place.onHit !== 'collect') t += ` ${s.place.onHit === 'press' ? 'press' : s.place.onHit === 'halfPress' ? 'half-press' : 'regress'}`;
    if (s.place.downAfterHits) t += `, down after ${s.place.downAfterHits} hit${s.place.downAfterHits > 1 ? 's' : ''}`;
    parts.push(t);
  }
  const lays = POINT_NUMBERS.filter((n) => s.lay.amounts[n] > 0);
  if (lays.length) parts.push(`Lay ${lays.join('/')}`);
  if (s.field.amount) parts.push(`Field ${money(s.field.amount)}`);
  const hards = HARD_NUMBERS.filter((n) => s.hard.amounts[n] > 0);
  if (hards.length) parts.push(`Hard ${hards.join('/')}`);
  const props = PROP_TYPES.filter((p) => s.props.amounts[p] > 0);
  if (props.length) parts.push(props.map((p) => PROPS[p].label).join(', '));
  const bigs = [6, 8].filter((n) => s.big.amounts[n] > 0);
  if (bigs.length) parts.push(`Big ${bigs.join('/')}`);
  if (s.progression.type !== 'flat') parts.push(`${PROGRESSIONS[s.progression.type].label} on ${s.progression.target}`);
  return parts.join(' · ') || 'No bets';
}

// ---------------------------------------------------------------------------
// Execution
// ---------------------------------------------------------------------------

const roundToUnit = (x, u) => Math.max(u, Math.round(x / u) * u);
const floorToUnit = (x, u) => Math.floor(x / u + 1e-9) * u;

const PLANS = new WeakMap();

/** Pre-compute the parts of a strategy the per-roll loop needs (cached per strategy object). */
function compilePlan(s) {
  let plan = PLANS.get(s);
  if (plan) return plan;
  plan = {
    minReq: Math.min(...strategyBets(s).map((b) => b.amount), Infinity),
    comes: [['come', s.come], ['dontCome', s.dontCome]].filter(([, c]) => c.count > 0).map(([type, cfg]) => ({ type, cfg })),
    places: ALL_BOX_NUMBERS.filter((n) => s.place.amounts[n] > 0).map((n) => ({ n, type: s.place.buy.includes(n) ? 'buy' : 'place' })),
    lays: POINT_NUMBERS.filter((n) => s.lay.amounts[n] > 0).map((n) => ({ n, amount: s.lay.amounts[n] })),
    hards: HARD_NUMBERS.filter((n) => s.hard.amounts[n] > 0).map((n) => ({ n, amount: s.hard.amounts[n] })),
    props: PROP_TYPES.filter((p) => s.props.amounts[p] > 0).map((p) => ({ type: p, amount: s.props.amounts[p] })),
    bigs: [6, 8].filter((n) => s.big.amounts[n] > 0).map((n) => ({ n, amount: s.big.amounts[n] })),
  };
  PLANS.set(s, plan);
  return plan;
}

export class StrategyExecutor {
  /**
   * @param {object} strategy
   * @param {object} rules
   * @param {{normalized?: boolean}} [opts] pass normalized:true to skip re-normalizing (hot loop)
   */
  constructor(strategy, rules, opts = {}) {
    this.s = opts.normalized ? strategy : normalizeStrategy(strategy);
    this.r = rules;
    this.plan = compilePlan(this.s);
    this.prog = new Progression(this.s.progression);
    this.base = this.s.place.amounts;
    this._minReq = this.plan.minReq;
    this.placeCur = { ...this.base };
    this.resetHand();
  }

  resetHand() {
    for (const n of ALL_BOX_NUMBERS) this.placeCur[n] = this.base[n];
    this.placeHits = 0;
    this.downForHand = false;
    this.regressed = false;
  }

  /** Smallest amount that lets this strategy keep playing. Below it (with an empty table) the player is busted. */
  minRequired() { return this._minReq; }

  _when(w, comeOut) {
    return w === 'always' || (w === 'pointOn' && !comeOut) || (w === 'comeOut' && comeOut);
  }

  /** Clamp a desired flat amount to table limits and what's in the rack. Returns 0 to skip. */
  _affordable(amount, type, number, sess) {
    const r = this.r;
    let a = Math.min(amount, r.tableMax);
    if (a > sess.bankroll) a = Math.floor(sess.bankroll);
    const min = minimumFor(type, number, r);
    return a >= min ? a : 0;
  }

  _targetOdds(bet, setting, sess) {
    if (!setting || bet.point === null) return 0;
    const max = sess.maxOddsFor(bet);
    if (setting === 'max') return max;
    const p = bet.point;
    const m = Math.min(setting, maxOddsMultiple(this.r, p));
    const exact = this.r.rounding === 'exact';
    if (bet.type === 'pass' || bet.type === 'come') {
      const raw = m * bet.amount;
      return Math.min(max, exact ? raw : roundToUnit(raw, UNITS.odds[p]));
    }
    const raw = (m * bet.amount) / LAY_ODDS[p]; // lay enough to win m × flat
    return Math.min(max, exact ? raw : Math.max(UNITS.lay[p], floorToUnit(raw, UNITS.lay[p])));
  }

  _topUpOdds(bet, setting, sess) {
    const target = this._targetOdds(bet, setting, sess);
    let diff = target - bet.odds;
    if (diff <= 1e-9) return;
    if (diff > sess.bankroll) {
      const unit = this.r.rounding === 'exact' ? 0.01 : (bet.type === 'pass' || bet.type === 'come' ? UNITS.odds[bet.point] : UNITS.lay[bet.point]);
      diff = floorToUnit(sess.bankroll, unit);
      if (diff <= 0) return;
    }
    sess.addOdds(bet, diff, { clamp: true });
  }

  /** Put the strategy's bets on the table for the next roll. */
  beforeRoll(sess) {
    const s = this.s, t = sess.table, comeOut = t.point === null, plan = this.plan;
    const mult = this.prog.mult;

    // 1) Line bet on the come-out roll.
    if (s.line.type !== 'none' && s.line.amount > 0 && comeOut && !t.find(s.line.type)) {
      const want = s.line.amount * (s.progression.target === 'line' ? mult : 1);
      const a = this._affordable(want, s.line.type, undefined, sess);
      if (a) sess.place(s.line.type, undefined, a);
    }
    // 2) Odds behind the line bet.
    if (!comeOut && s.line.type !== 'none' && s.line.odds) {
      const lb = t.find(s.line.type);
      if (lb && lb.point !== null) this._topUpOdds(lb, s.line.odds, sess);
    }
    // 3) Come / Don't Come bets (one "in the box" at a time) and their odds.
    for (let ci = 0; ci < plan.comes.length; ci++) {
      const { type, cfg } = plan.comes[ci];
      let pending = null, established = 0;
      const bets = t.bets;
      for (let i = 0; i < bets.length; i++) {
        const b = bets[i];
        if (b.type !== type) continue;
        if (b.point === null) pending = b; else { established++; if (cfg.odds) this._topUpOdds(b, cfg.odds, sess); }
      }
      if (!comeOut && !pending && established < cfg.count) {
        const a = this._affordable(cfg.amount, type, undefined, sess);
        if (a) sess.place(type, undefined, a);
      }
    }
    // 4) Place / Buy bets.
    if (plan.places.length) {
      const pl = s.place;
      const placeOn = this._when(pl.when, comeOut);
      for (let i = 0; i < plan.places.length; i++) {
        const { n, type } = plan.places[i];
        const existing = t.find(type, n);
        const skip = this.downForHand || (pl.skipCovered && this._isCovered(t, n));
        if (skip) { if (existing) sess.takeDown(existing); continue; }
        const want = this.placeCur[n];
        if (!existing) {
          if (placeOn) {
            const a = this._affordable(want, type, n, sess);
            if (a) sess.place(type, n, a);
          }
        } else if (existing.amount < want - 1e-9) {
          const add = Math.min(want - existing.amount, Math.floor(sess.bankroll), this.r.tableMax - existing.amount);
          if (add > 0) sess.place(type, n, add);
        } else if (existing.amount > want + 1e-9) {
          sess.reduce(existing, want);
        }
      }
    }
    // 5) Lay bets.
    if (plan.lays.length && this._when(s.lay.when, comeOut)) {
      for (const { n, amount } of plan.lays) {
        if (t.find('lay', n)) continue;
        const a = this._affordable(amount, 'lay', n, sess);
        if (a) sess.place('lay', n, a);
      }
    }
    // 6) Field (one-roll).
    if (s.field.amount > 0 && this._when(s.field.when, comeOut)) {
      const want = s.field.amount * (s.progression.target === 'field' ? mult : 1);
      const a = this._affordable(want, 'field', undefined, sess);
      if (a) sess.place('field', undefined, a);
    }
    // 7) Hardways (re-bet after a loss).
    if (plan.hards.length && this._when(s.hard.when, comeOut)) {
      for (const { n, amount } of plan.hards) {
        if (t.find('hard', n)) continue;
        const a = this._affordable(amount, 'hard', n, sess);
        if (a) sess.place('hard', n, a);
      }
    }
    // 8) One-roll props.
    if (plan.props.length && this._when(s.props.when, comeOut)) {
      for (const { type, amount } of plan.props) {
        const a = this._affordable(amount, type, undefined, sess);
        if (a) sess.place(type, undefined, a);
      }
    }
    // 9) Big 6 / Big 8.
    for (const { n, amount } of plan.bigs) {
      if (t.find('big', n)) continue;
      const a = this._affordable(amount, 'big', n, sess);
      if (a) sess.place('big', n, a);
    }
  }

  _isCovered(t, n) {
    for (const b of t.bets) if ((b.type === 'pass' || b.type === 'come') && b.point === n) return true;
    return false;
  }

  /** React to the roll: progressions, presses, regressions, resets. */
  afterRoll(sess, res) {
    const s = this.s;
    for (const ev of res.events) {
      if (ev.outcome !== 'win' && ev.outcome !== 'lose' && ev.outcome !== 'push') continue;
      if (s.progression.target === 'line' && ev.key === s.line.type) this.prog.record(ev.outcome);
      else if (s.progression.target === 'field' && ev.key === 'field') this.prog.record(ev.outcome);
      if (ev.outcome === 'win' && (ev.evType === 'place' || ev.evType === 'buy')) this._onPlaceHit(ev.number, ev.evType);
    }
    if (res.sevenOut) this.resetHand();
  }

  _onPlaceHit(n, type) {
    const pl = this.s.place, r = this.r;
    this.placeHits++;
    const unit = r.rounding === 'exact' ? 0.01 : (type === 'buy' ? UNITS.buy[n] : UNITS.place[n]);
    const cap = this.base[n] * pl.maxPress;
    if (pl.onHit === 'press') this.placeCur[n] = Math.min(cap, this.placeCur[n] * 2);
    else if (pl.onHit === 'halfPress') this.placeCur[n] = Math.min(cap, this.placeCur[n] + Math.max(unit, floorToUnit(this.placeCur[n] / 2, unit)));
    else if (pl.onHit === 'regress' && !this.regressed) {
      this.regressed = true;
      for (const k of ALL_BOX_NUMBERS) {
        if (this.base[k] > 0) this.placeCur[k] = Math.min(this.base[k], minimumFor(pl.buy.includes(k) ? 'buy' : 'place', k, r));
      }
    }
    if (pl.downAfterHits > 0 && this.placeHits >= pl.downAfterHits) this.downForHand = true;
  }

  /** End of session: take down every bet that can come down; contract bets play out. */
  windDown(sess) {
    for (const b of [...sess.table.bets]) if (STANDING_TYPES.has(b.type)) sess.takeDown(b);
  }
}

export { ODDS_LIMITS };
